// Consistency model choices in a real Node.js application
// Scenario: user updates their display name, then immediately views their profile

// ─── OPTION A: Eventual Consistency (default — stale read possible) ───────────
async function updateProfileEventual(userId, name) {
  // Write lands on the primary
  await dynamoDB.put({ TableName: 'Users', Item: { userId, name } });

  // Read immediately — might return old name from a lagging replica!
  const user = await dynamoDB.get({
    TableName: 'Users',
    Key: { userId },
    ConsistentRead: false  // default: eventually consistent, cheaper
  });

  // DANGER: user.name may still be the OLD name here
  // This violates read-your-writes — a real user-facing bug
  return user.name;
}

// ─── OPTION B: Linearizable Read ──────────────────────────────────────────────
async function updateProfileStrong(userId, name) {
  await dynamoDB.put({ TableName: 'Users', Item: { userId, name } });

  // ConsistentRead: true forces the read to go to the primary partition
  // Guarantees reading the most recent committed write — linearizable
  // Cost: 2x read capacity units consumed, higher latency
  const user = await dynamoDB.get({
    TableName: 'Users',
    Key: { userId },
    ConsistentRead: true
  });

  return user.name; // guaranteed to be the new name
}

// ─── OPTION C: Read-Your-Writes via Client-Side Write Cache ───────────────────
const writeCache = new Map(); // { key => { value, expiresAt } }
const CACHE_TTL_MS = 5000;    // 5 seconds — long enough for replication lag

async function updateProfileRYW(userId, name) {
  await dynamoDB.put({ TableName: 'Users', Item: { userId, name } });

  // Cache the write locally — this client session will always see it
  writeCache.set(userId, { name, expiresAt: Date.now() + CACHE_TTL_MS });

  const cached = writeCache.get(userId);
  if (cached && cached.expiresAt > Date.now()) {
    return cached.name; // serves own write from cache — no DB call needed
  }

  // Cache expired: replication should have caught up by now
  const user = await dynamoDB.get({ TableName: 'Users', Key: { userId } });
  return user.name;
}

// ─── OPTION D: Token-Based Read-After-Write (version propagation) ─────────────
async function updateProfileToken(userId, name) {
  const response = await dynamoDB.put({ TableName: 'Users', Item: { userId, name } });
  const writeVersion = response.ConsumedCapacity?.CapacityUnits; // or a logical clock

  // Pass version token to read; replica refuses to serve until it catches up
  // (Cosmos DB and some custom systems support this pattern natively)
  const user = await dynamoDB.get({
    TableName: 'Users',
    Key: { userId },
    // Hypothetical: some databases accept a min-version parameter
    // MinVersion: writeVersion
  });
  return user.name;
}

// CRDTs illustrated: G-Counter and LWW-Register

// ── G-Counter (grow-only, convergent counter) ─────────────────────────────────
class GCounter {
  constructor(nodeId, totalNodes) {
    this.nodeId = nodeId;
    this.counts = new Array(totalNodes).fill(0); // one slot per node
  }

  increment() {
    this.counts[this.nodeId]++;
  }

  value() {
    // Global count = sum of all per-node counts
    return this.counts.reduce((sum, c) => sum + c, 0);
  }

  // Merge: take component-wise maximum — always commutative and idempotent
  merge(other) {
    this.counts = this.counts.map((c, i) => Math.max(c, other.counts[i]));
  }
}

// Simulate two nodes incrementing independently, then merging
const node0 = new GCounter(0, 2);
const node1 = new GCounter(1, 2);

node0.increment(); // node0 counts: [1, 0] → value = 1
node0.increment(); // node0 counts: [2, 0] → value = 2
node1.increment(); // node1 counts: [0, 1] → value = 1

// Network partition heals — nodes exchange state
node0.merge(node1); // node0 counts: [2, 1] → value = 3
node1.merge(node0); // node1 counts: [2, 1] → value = 3

console.log(node0.value()); // 3 — both nodes converge to same value
console.log(node1.value()); // 3 — regardless of merge order

// ── LWW-Register (last-write-wins — simple value CRDT) ───────────────────────
class LWWRegister {
  constructor() {
    this.value = null;
    this.timestamp = 0;
  }

  write(value, timestamp) {
    if (timestamp > this.timestamp) {
      this.value = value;
      this.timestamp = timestamp;
    }
  }

  // Merge: keep the value with the higher timestamp
  merge(other) {
    if (other.timestamp > this.timestamp) {
      this.value = other.value;
      this.timestamp = other.timestamp;
    }
  }
}

const regA = new LWWRegister();
const regB = new LWWRegister();

regA.write('Alice', 100);
regB.write('Bob', 105); // concurrent write with later timestamp

regA.merge(regB);
regB.merge(regA);

console.log(regA.value); // 'Bob' — higher timestamp wins
console.log(regB.value); // 'Bob' — both converge
// NOTE: 'Alice' write is silently lost — this is the LWW trade-off
